mapper.select:
SELECT COUNT(*)
FROM ${tableName}
WHERE owned_enterprise_code = #{ownedEnterpriseCode}
AND apply_staff_code = #{applyStaffCode}
AND process_run_code = #{processRunCode}
AND process_status = -1

    AND #{tablePrimaryKey} = ANY(table_primary_key_list) AND array_length(table_primary_key_list, 1) = 1

SELECT t1.description, t1.update_time saveTime, t1.step_code, t1.process_code
FROM ${tableNameStep} t1
LEFT JOIN ${tableName} t2 ON t1.process_code = t2.process_code
WHERE t2.owned_enterprise_code = #{ownedEnterpriseCode}
AND t2.apply_staff_code = #{applyStaffCode}
AND t2.process_run_code = #{processRunCode}
AND t2.process_status = -1

    AND #{tablePrimaryKey} = ANY(t2.table_primary_key_list) AND array_length(t2.table_primary_key_list, 1) = 1

SELECT process_code, owned_enterprise_code, process_run_code, table_primary_key_list::BIGINT[], apply_staff_code, next_code, transfer_info, process_step_info, process_form_info, process_status, create_time, update_time, delete_flag FROM ${tableName} WHERE delete_flag = false AND owned_enterprise_code = #{enterpriseCode}
AND (apply_staff_code = #{staffCode} OR transfer_info LIKE '%'||'-'||#{staffCode}||'%' OR ( next_code IN
#{nodeCode}
AND transfer_info NOT LIKE '%'||#{staffCode}||'-'||'%'))
AND process_status = #{processStatus}
AND process_status > 0
AND transfer_info = ''
AND transfer_info !=''
AND process_code = #{processCode}
ORDER BY process_status ASC, transfer_info DESC , update_time DESC

mapper.update:
UPDATE ${tableName}
SET process_status = 11
WHERE process_code = #{processCode}
  AND apply_staff_code = #{applyStaffCode}
  AND owned_enterprise_code = #{enterpriseCode}
  AND process_status = 5

